'use client';

import React, { useState, Children, isValidElement } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';

export function FlashcardDeck({ children }: { children: React.ReactNode }) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [direction, setDirection] = useState(1);

  const cards = Children.toArray(children).filter(isValidElement);
  const totalCards = cards.length;

  if (totalCards === 0) {
    return <p className="text-fd-muted-foreground my-8 text-center">No flashcards provided.</p>;
  }

  const goNext = () => {
    setDirection(1);
    setCurrentIndex((prev) => (prev + 1) % totalCards);
  };

  const goPrev = () => {
    setDirection(-1);
    setCurrentIndex((prev) => (prev - 1 + totalCards) % totalCards);
  };

  const animationClass = direction === 1 
    ? "animate-in fade-in slide-in-from-right-8 duration-300" 
    : "animate-in fade-in slide-in-from-left-8 duration-300";

  return (
    <div className="my-8 rounded-xl border border-fd-border bg-fd-background p-6 shadow-sm">
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-lg font-bold text-fd-foreground">Flashcard Deck</h3>
        <span className="text-sm font-medium text-fd-muted-foreground bg-fd-muted px-3 py-1 rounded-full">
          Card {currentIndex + 1} of {totalCards}
        </span>
      </div>

      <div className="min-h-[280px] flex items-center justify-center p-4 overflow-hidden">
        <div key={currentIndex} className={`w-full ${animationClass}`}>
          {cards[currentIndex]}
        </div>
      </div>

      <div className="flex justify-between items-center mt-6 pt-4 border-t border-fd-border">
        <button
          onClick={goPrev}
          className="flex items-center gap-2 px-4 py-2 rounded-lg border border-fd-border bg-fd-background hover:bg-fd-muted transition-colors text-sm font-medium text-fd-foreground"
        >
          <ChevronLeft className="h-4 w-4" /> Previous
        </button>
        <button
          onClick={goNext}
          className="flex items-center gap-2 px-4 py-2 rounded-lg bg-fd-primary text-fd-primary-foreground hover:bg-fd-primary/90 transition-colors text-sm font-medium shadow-sm"
        >
          Next <ChevronRight className="h-4 w-4" />
        </button>
      </div>
    </div>
  );
}
